class VerifyRecoveryDiagnosticsTests(unittest.TestCase):
    def _document(self, **overrides) -> dict:
        document = {
            "format": "branching-city-twin/recovery-diagnostic",
            "version": 1,
            "transaction": "a" * 64,
            "prev": "0" * 64,
            "phase": "index",
            "index": {"state": "new", "matches": "new"},
            "progress": {"state": "old", "matches": "old"},
            "backups": {
                "index": {"present": True, "intact": True},
                "progress": {"present": True, "intact": True},
            },
            "disposition": "pending_rollback",
            "reason": "pending_rollback",
            "checksum": "",
        }
        document.update(overrides)
        return document

    def test_empty_tuple_is_true(self) -> None:
        self.assertTrue(
            BranchStore.verify_recovery_diagnostics(())
        )

    def test_container_and_element_types(self) -> None:
        with self.assertRaises(TypeError):
            BranchStore.verify_recovery_diagnostics([])  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            BranchStore.verify_recovery_diagnostics(("ok", 1))  # type: ignore[arg-type]
        with self.assertRaises(TypeError):
            BranchStore.verify_recovery_diagnostics(None)  # type: ignore[arg-type]

    def test_first_record_must_root_at_genesis(self) -> None:
        text = reseal(self._document(prev="1" * 64))
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics((text,))
        )

    def test_first_record_cannot_be_terminal(self) -> None:
        terminal_shape = {
            "phase": "",
            "index": {"state": "present", "matches": ""},
            "progress": {"state": "present", "matches": ""},
            "backups": {
                "index": {"present": False, "intact": False},
                "progress": {"present": False, "intact": False},
            },
        }
        text = reseal(
            self._document(
                disposition="committed",
                reason="committed",
                **terminal_shape,
            )
        )
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics((text,))
        )

    def test_unreachable_pending_observation_is_invalid(self) -> None:
        # Both targets on old bytes can never be pending_commit.
        text = reseal(
            self._document(
                phase="progress",
                index={"state": "old", "matches": "old"},
                progress={"state": "old", "matches": "old"},
                disposition="pending_commit",
                reason="pending_commit",
            )
        )
        with self.assertRaises(ValueError):
            BranchStore.verify_recovery_diagnostics((text,))
        # A new target that a rollback would restore needs its backup.
        text = reseal(
            self._document(
                backups={
                    "index": {"present": False, "intact": False},
                    "progress": {"present": True, "intact": True},
                },
            )
        )
        with self.assertRaises(ValueError):
            BranchStore.verify_recovery_diagnostics((text,))

    def test_broken_prev_link_returns_false(self) -> None:
        first_doc = json.loads(reseal(self._document()))
        terminal_shape = {
            "phase": "",
            "index": {"state": "present", "matches": ""},
            "progress": {"state": "present", "matches": ""},
            "backups": {
                "index": {"present": False, "intact": False},
                "progress": {"present": False, "intact": False},
            },
        }
        second_text = reseal(
            self._document(
                prev="f" * 64,
                disposition="rolled_back",
                reason="rolled_back",
                **terminal_shape,
            )
        )
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (
                    BranchStore._canonical_json(first_doc),
                    second_text,
                )
            )
        )

    def test_transaction_mutation_returns_false(self) -> None:
        first = reseal(self._document())
        second = json.loads(first)
        second["transaction"] = "b" * 64
        second["prev"] = json.loads(first)["checksum"]
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (first, reseal(second))
            )
        )

    def test_forbidden_transitions_return_false(self) -> None:
        first = reseal(self._document())
        chain_head = json.loads(first)["checksum"]

        def successor(**overrides) -> str:
            return reseal(self._document(prev=chain_head, **overrides))

        terminal_shape = {
            "phase": "",
            "index": {"state": "present", "matches": ""},
            "progress": {"state": "present", "matches": ""},
            "backups": {
                "index": {"present": False, "intact": False},
                "progress": {"present": False, "intact": False},
            },
        }
        # pending_rollback cannot become committed or stay evidence-new
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (
                    first,
                    successor(
                        disposition="committed",
                        reason="committed",
                        **terminal_shape,
                    ),
                )
            )
        )
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (
                    first,
                    successor(
                        disposition="pending_commit",
                        reason="pending_commit",
                        phase="progress",
                        index={"state": "new", "matches": "new"},
                        progress={"state": "new", "matches": "new"},
                    ),
                )
            )
        )
        # rolled_back cannot go back to pending.
        rolled_back = successor(
            disposition="rolled_back",
            reason="rolled_back",
            **terminal_shape,
        )
        rolled_doc = json.loads(rolled_back)
        again = reseal(
            self._document(
                prev=rolled_doc["checksum"],
                disposition="pending_rollback",
                reason="pending_rollback",
            )
        )
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (first, rolled_back, again)
            )
        )

    def test_terminal_state_carries_forward(self) -> None:
        first = reseal(self._document())
        head = json.loads(first)["checksum"]
        terminal_shape = {
            "phase": "",
            "index": {"state": "present", "matches": ""},
            "progress": {"state": "present", "matches": ""},
            "backups": {
                "index": {"present": False, "intact": False},
                "progress": {"present": False, "intact": False},
            },
        }
        settled = reseal(
            self._document(
                prev=head,
                disposition="rolled_back",
                reason="rolled_back",
                **terminal_shape,
            )
        )
        carried = reseal(
            self._document(
                prev=json.loads(settled)["checksum"],
                disposition="rolled_back",
                reason="rolled_back",
                **terminal_shape,
            )
        )
        self.assertTrue(
            BranchStore.verify_recovery_diagnostics(
                (first, settled, carried)
            )
        )

    def test_phase_regression_returns_false(self) -> None:
        # Same pending disposition, but the observed phase moves from
        # "index" back to "prepared": the evidence regressed.
        first = reseal(self._document(phase="index"))
        regressed = reseal(
            self._document(
                prev=json.loads(first)["checksum"],
                phase="prepared",
                index={"state": "old", "matches": "old"},
                progress={"state": "old", "matches": "old"},
            )
        )
        self.assertFalse(
            BranchStore.verify_recovery_diagnostics(
                (first, regressed)
            )
        )

    def test_malformed_records_raise_value_error(self) -> None:
        good = json.loads(reseal(self._document()))
        cases = []
        # Non-canonical JSON (whitespace).
        cases.append(json.dumps(good, indent=2))
        # Duplicate key.
        cases.append(
            BranchStore._canonical_json(good)[:-1]
            + ',"reason":"pending_rollback"}'
        )
        # Unsupported version (checksum resealed).
        cases.append(reseal(self._document(version=2)))
        # Extra key.
        cases.append(reseal(self._document(extra=1)))
        # Unknown disposition.
        cases.append(
            reseal(self._document(disposition="halfway"))
        )
        # State/matches disagreement.
        cases.append(
            reseal(
                self._document(
                    index={"state": "new", "matches": "old"}
                )
            )
        )
        # Intact backup that is absent.
        cases.append(
            reseal(
                self._document(
                    backups={
                        "index": {"present": False, "intact": True},
                        "progress": {"present": True, "intact": True},
                    }
                )
            )
        )
        # Bad checksum (no reseal).
        tampered = self._document()
        tampered["checksum"] = "f" * 64
        cases.append(
            BranchStore._canonical_json(tampered)
        )
        for case in cases:
            with self.subTest(case=case[:32]):
                with self.assertRaises(ValueError):
                    BranchStore.verify_recovery_diagnostics((case,))


class ArgumentValidationTests(RecoveryPublicationTestBase):
    def setUp(self) -> None:
        super().setUp()
        self.grow_chain(2)

    def test_path_types(self) -> None:
        for bad in (1, 1.5, b"x", ["x"], {"x": 1}, object(), None):
            with self.subTest(bad=type(bad).__name__):
                with self.assertRaises(TypeError):
                    BranchStore.recovery_diagnostic(
                        bad, self.progress, self.recovery  # type: ignore[arg-type]

def _parse_recovery_diagnostic(cls, text: Any) -> dict[str, Any]:
    """Strictly parse and authenticate one diagnostic string,
    returning its normalized mapping. Any encoding, JSON,
    canonical-form, duplicate-key, field, type, version, domain,
    cross-field consistency or checksum defect raises
    :class:`ValueError`. The caller validates that ``text`` is a
    non-empty :class:`str`."""
    if not isinstance(text, str):
        raise TypeError(
            f"diagnostic must be a str, got {type(text).__name__}"
        )
    if text.startswith("\ufeff"):
        raise ValueError("diagnostic must be UTF-8 without a BOM")
    try:
        document = json.loads(
            text,
            object_pairs_hook=cls._reject_duplicate_json_keys,
        )
    except ValueError as exc:
        raise ValueError(f"diagnostic is not valid JSON: {exc}")
    if cls._canonical_json(document) != text:
        raise ValueError("diagnostic is not canonical compact JSON")
    if not isinstance(document, dict) or set(document) != set(
        cls._RECOVERY_DIAGNOSTIC_KEYS
    ):
        raise ValueError("diagnostic has bad top-level keys")
    if document["format"] != cls._RECOVERY_DIAGNOSTIC_FORMAT:
        raise ValueError("diagnostic has an unknown format")
    version = document["version"]
    if (
        isinstance(version, bool)
        or not isinstance(version, int)
        or version not in cls._RECOVERY_DIAGNOSTIC_SUPPORTED_VERSIONS
    ):
        raise ValueError("diagnostic has an unsupported version")

    def is_digest(value: Any, allow_empty: bool = False) -> bool:
        if not isinstance(value, str):
            return False
        if allow_empty and value == "":
            return True
        return len(value) == 64 and not (
            set(value) - cls._HEX_DIGITS
        )

    transaction = document["transaction"]
    if not is_digest(transaction, allow_empty=True):
        raise ValueError("diagnostic transaction is malformed")
    prev = document["prev"]
    if not is_digest(prev):
        raise ValueError("diagnostic prev digest is malformed")
    phase = document["phase"]
    if not isinstance(phase, str) or phase not in (
        cls._RECOVERY_DIAGNOSTIC_PHASES
    ):
        raise ValueError("diagnostic phase is unknown")

    def parse_target(value: Any) -> dict[str, str]:
        if not isinstance(value, dict) or set(value) != set(
            cls._RECOVERY_DIAGNOSTIC_TARGET_KEYS
        ):
            raise ValueError("diagnostic target has bad keys")
        state = value["state"]
        matches = value["matches"]
        if (
            not isinstance(state, str)
            or state not in cls._RECOVERY_DIAGNOSTIC_TARGET_STATES
        ):
            raise ValueError("diagnostic target state is unknown")
        if not isinstance(matches, str):
            raise ValueError("diagnostic target matches must be a str")
        allowed_matches = {
            cls._RECOVERY_DIAGNOSTIC_TARGET_PRESENT: {""},
            cls._RECOVERY_DIAGNOSTIC_TARGET_NEW: {
                cls._RECOVERY_DIAGNOSTIC_MATCH_NEW
            },
            cls._RECOVERY_DIAGNOSTIC_TARGET_OLD: {
                cls._RECOVERY_DIAGNOSTIC_MATCH_OLD
            },
            cls._RECOVERY_DIAGNOSTIC_TARGET_SAME: {
                cls._RECOVERY_DIAGNOSTIC_MATCH_BOTH
            },
            cls._RECOVERY_DIAGNOSTIC_TARGET_UNKNOWN: {""},
        }
        if matches not in allowed_matches[state]:
            raise ValueError(
                "diagnostic target state and matches disagree"
            )
        return {"state": state, "matches": matches}

    targets = {
        label: parse_target(document[label])
        for label in ("index", "progress")
    }

    backups_value = document["backups"]
    if not isinstance(backups_value, dict) or set(
        backups_value
    ) != set(cls._RECOVERY_DIAGNOSTIC_BACKUPS_KEYS):
        raise ValueError("diagnostic backups have bad keys")

    def parse_backup(value: Any) -> dict[str, bool]:
        if not isinstance(value, dict) or set(value) != set(
            cls._RECOVERY_DIAGNOSTIC_BACKUP_KEYS
        ):
            raise ValueError("diagnostic backup has bad keys")
        present = value["present"]
        intact = value["intact"]
        if not isinstance(present, bool) or not isinstance(
            intact, bool
        ):
            raise ValueError(
                "diagnostic backup flags must be bools"
            )
        if not present and intact:
            raise ValueError(
                "diagnostic backup cannot be intact when absent"
            )
        return {"present": present, "intact": intact}

    backups = {
        label: parse_backup(backups_value[label])
        for label in ("index", "progress")
    }

    disposition = document["disposition"]
    reason = document["reason"]
    if (
        not isinstance(disposition, str)
        or disposition not in cls._RECOVERY_DIAGNOSTIC_DISPOSITIONS
    ):
        raise ValueError("diagnostic disposition is unknown")
    if not isinstance(reason, str) or reason not in (
        cls._RECOVERY_DIAGNOSTIC_REASONS
    ):
        raise ValueError("diagnostic reason is unknown")
    checksum = document["checksum"]
    if not is_digest(checksum):
        raise ValueError("diagnostic checksum is malformed")

def _require_record_limit(value: Any, name: str) -> int:
    """Validate one non-``bool`` record-count cap of at least one."""
    limit_value = BranchStore._require_size_bound(value, name)
    if limit_value < 1:
        raise ValueError(f"{name} must be >= 1")
    return limit_value

@staticmethod
def _require_checkpoint_index(value: Any, name: str) -> int:
    """Validate one non-``bool`` checkpoint index parameter."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{name} checkpoint index must be an int, got "
            f"{type(value).__name__}"
        )
    return value

@staticmethod
def _frontier_point_count(validated: dict[str, object]) -> int:
    """Return the checkpoint count every series plan is aligned to."""
    per_series = validated["per_series"]
    if not per_series:
        return 0
    return len(per_series[0][1])

@staticmethod
def _prefix_frontier_view(
    prepared: dict[str, object], length: int
) -> dict[str, object]:
    """Restrict a captured frozen view to its first ``length`` checkpoints.

    Only the per-series checkpoint views are shortened; candidates,
    values, weights and budgets are unchanged, so building a cascade on
    the result equals running the existing query with series truncated
    to that checkpoint prefix. Both prefixes of a diff derive from the
    same captured view, merely taking shorter copies of its orders.
    """
    prefix_views: dict[
        str, list[tuple[list[str], list[str], str, str]]
    ] = {

def _validate_chain_timeout(cls, timeout: Any) -> None:
    """Validate an append ``timeout`` argument: ``None`` (wait
    indefinitely) or a non-``bool`` :class:`int`/:class:`float`
    number of seconds. Any other type raises :class:`TypeError`; a
    negative value, NaN or either infinity raises
    :class:`ValueError`."""
    if timeout is None:
        return
